template<class T>struct C{int dormant();};
template<class T>int C<T>::dormant(){return sizeof(typename T::missing);}
extern template struct C<int>;int main(){C<int> c;return c.dormant();}

template<class T>struct C{struct Inner{int dormant();};};
template<class T>int C<T>::Inner::dormant(){return sizeof(typename T::missing);}
extern template struct C<int>;int main(){C<int>::Inner c;return c.dormant();}
